import React from 'react';
import { motion } from 'framer-motion';
import * as Lucide from 'lucide-react';

export const SurfingWaveMetric: React.FC<SurfingWaveMetricProps> = ({ data }) => {
  if (!data) return null;

  return (
    <div className="w-full h-full p-8 rounded-3xl border border-slate-100 shadow-xl shadow-slate-200/50 bg-white relative overflow-hidden">
      <div className="flex items-start justify-between gap-6">
        <div className="min-w-0">
          <div className="text-sm font-medium uppercase tracking-wider text-slate-500">{data.title}</div>
          <div className="mt-3 grid grid-cols-2 gap-6">
            <div className="min-w-0">
              <div className="text-sm font-medium uppercase tracking-wider text-slate-500">{data.primaryLabel}</div>
              <div className="text-4xl font-bold tracking-tight text-blue-600">{data.primaryValue}</div>
            </div>
            <div className="min-w-0">
              <div className="text-sm font-medium uppercase tracking-wider text-slate-500">{data.secondaryLabel}</div>
              <div className="text-4xl font-bold tracking-tight text-emerald-600">{data.secondaryValue}</div>
            </div>
          </div>
          {data.footnote ? (
            <div className="mt-4 text-sm text-slate-500">{data.footnote}</div>
          ) : null}
        </div>

        <div className="shrink-0" aria-label="Momentum indicator">
          <Lucide.Waves className="w-6 h-6 text-blue-600" aria-label="Waves icon" />
        </div>
      </div>

      <motion.svg
        className="absolute inset-0 w-full h-full"
        viewBox="0 0 100 100"
        preserveAspectRatio="none"
        aria-label="Animated wave background"
      >
        <motion.path
          d="M 0 62 C 18 48, 32 76, 50 62 C 68 48, 82 76, 100 62"
          fill="none"
          stroke="currentColor"
          className="text-blue-600"
          strokeWidth="2"
          strokeLinecap="round"
          initial={{ pathLength: 0, opacity: 0.2 }}
          animate={{ pathLength: 1, opacity: 0.2 }}
          transition={{ duration: 1.6, ease: 'easeInOut' }}
        />
      </motion.svg>
    </div>
  );
};
